var exec=require('cordova/exec');module.exports={capture:function(ok,fail){exec(ok,fail,'NearbyPhotos','capture',[]);},nearby:function(lat,lon,radius,ok,fail){exec(ok,fail,'NearbyPhotos','nearby',[lat,lon,radius]);},thumbnail:function(id,ok,fail){exec(ok,fail,'NearbyPhotos','thumbnail',[id]);},renameAlbum:function(collectionId,newName,ok,fail){exec(ok,fail,'NearbyPhotos','renameAlbum',[collectionId,newName]);},addToAlbum:function(collectionId,title,ids,ok,fail){exec(ok,fail,'NearbyPhotos','addToAlbum',[collectionId,title,ids]);},listAlbumAssets:function(collectionId,offset,limit,ok,fail){exec(ok,fail,'NearbyPhotos','listAlbumAssets',[collectionId,offset,limit]);},preview:function(id,ok,fail){exec(ok,fail,'NearbyPhotos','thumbnail',[id,1280]);},pick:function(ok,fail){exec(ok,fail,'NearbyPhotos','pick',[]);}};